import sys, wave
import numpy as np
from pathlib import Path

def read(p):
    with wave.open(str(p),'rb') as f:
        bits, rate, ch = f.getsampwidth(), f.getframerate(), f.getnchannels()
        dt = '<i2' if bits == 2 else '<i4'
        y = np.frombuffer(f.readframes(f.getnframes()),dtype=dt).astype(np.float64).reshape(-1,ch)/(2**(bits*8-1))
    return rate,y

def write(p, sr, y):
    with wave.open(str(p),'wb') as f:
        f.setparams((y.shape[1],2,sr,len(y),'NONE','not compressed'))
        f.writeframes(np.round(np.clip(y,-1,32767/32768)*32768).astype('<i2').tobytes())

def db(a):
    return 20*np.log10(np.maximum(a,1e-9))

def rms(y, axis=None):
    return np.sqrt(np.mean(y*y,axis=axis))

def spectrum(y,fs,N=8192):
    h = np.hanning(N)
    step = N//2
    stk = np.lib.stride_tricks.sliding_window_view(y,N,axis=0)[::step]
    q = (np.abs(np.fft.rfft(stk*h,axis=-1))**2).mean(axis=0)
    q[...,1:-1] *= 2
    return np.fft.rfftfreq(N,1/fs), q/(N*np.sum(h*h))

def k_weight(f, ps, fs):
    z = np.exp(-2j*np.pi*f/fs)
    b1 = np.array([1.53512485958697,-2.69169618940638,1.19839281085285]); a1 = np.array([1,-1.69065929318241,0.73248077421585]);
    b2 = np.array([1,-2,1]); a2 = np.array([1,-1.99004745483398,0.99007225036621]);
    v = abs(np.polynomial.polynomial.polyval(z,b1)*np.polynomial.polynomial.polyval(z,b2)/(np.polynomial.polynomial.polyval(z,a1)*np.polynomial.polynomial.polyval(z,a2)))**2
    return ps*v

def level(y,fs):
    f, ps = spectrum(y,fs)
    p = k_weight(f,ps,fs)
    return 10*np.log10(p.sum()+1e-20)-.691


def stats(p,*selection):
    sr,a = read(p)
    frames = a.shape[0]
    bar_frames = (sr//1) * 1.666
    if selection:
        a = a[round(bar_frames*int(selection[0])):round(bar_frames*int(selection[1]))]
    y = a
    f, ps = spectrum(y,sr)
    bds = [0,40,100,170,350,600,1200,2000,4000,8000,12800,24001]
    spec = [10*np.log10(np.clip(ps[:,(f>=lo)&(f<hi)].sum(axis=1).mean(),1e-14,None)) for lo,hi in zip(bds,bds[1:])]
    print(f'{p.stem:7}',f'{db(abs(y).max()):6.1f} {db(rms(y)):6.1f} {10*np.log10(k_weight(f,ps,sr).sum()+1e-20)-.69:6.1f} {db(rms((y[:,0]-y[:,1])/(y[:,0]+y[:,1]+1e-12))):6.1f}' if False else f'{db(abs(y).max()):6.1f} {db(rms(y)):6.1f} {10*np.log10(k_weight(f,ps,sr).sum()+1e-20)-.69:6.1f} {db(rms(y[:,0]-y[:,1])/rms(y[:,0]+y[:,1])):6.1f}', ''.join(f'{t:6.1f}' for t in spec))

if __name__=='__main__':
    pp = Path(sys.argv[1])
    ps = sorted(pp.glob('*.wav')) if pp.is_dir() else [pp]
    sel = sys.argv[2:]
    print('stem      peak    rms  LKavg    S/M     [0,40,100,170,350,600,1200,2000,4000,8000,12800,24001]')
    for p in ps: stats(p,*sel)
